const KNOWLEDGE={clean:{en:'clean',cn:'干净的',scene:'clean',priority:3},room:{en:'room',cn:'房间',scene:'room',priority:2},dirty:{en:'dirty',cn:'脏的',scene:'dirty',priority:4},tidy:{en:'tidy',cn:'整理',scene:'tidy',priority:5},not:{en:'not',cn:'不 / 否定',scene:'dirty',priority:0},sentence:{en:'This room is not clean.',cn:'这个房间不干净。',scene:'dirty',priority:1},wash:{en:'wash hands',cn:'洗手',scene:'hands',priority:6}};
const STORIES=[{en:'This is my room.',cn:'这是我的房间。',key:'room',scene:'room'},{en:'This room is not clean.',cn:'这个房间不干净。',key:'not',scene:'dirty'},{en:'Let’s tidy the room.',cn:'我们来整理房间吧。',key:'tidy',scene:'tidy'},{en:'Look! This room is clean.',cn:'看！这个房间干净啦。',key:'clean',scene:'clean'}];
