const QUIZ=[{key:'clean',title:'听一听、看一看：哪一个房间是 clean？',type:'picture',options:[{label:'干净的房间',scene:'clean'},{label:'玩具散落的房间',scene:'dirty'}],correct:0,en:'clean'},{key:'room',title:'room 是哪一张图？',type:'picture',options:[{label:'房间',scene:'room'},{label:'洗手',scene:'hands'}],correct:0,en:'room'},{key:'not',title:'房间不干净。哪句话说对了？',type:'sentence',options:[{label:'This room is clean.'},{label:'This room is not clean.'}],correct:1,en:'This room is not clean.'},{key:'wash',title:'吃饭前，小手脏了，应该做什么？',type:'picture',options:[{label:'wash hands',scene:'hands'},{label:'继续玩玩具',scene:'dirty'}],correct:0,en:'wash hands'}];
const STORAGE='xueli-product-demo-v2';
