let state,newId=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),timer=null,speechTimer=null,speechSeq=0,panelSpeech='',chatOpen=false,toastTimer=null,activeReport=null;
const stage=document.querySelector('#stage'),main=document.querySelector('#main'),ai=document.querySelector('#ai-layer');
function escapeHtml(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function beginState(view='library'){return {id:newId(),view,module:0,index:0,sub:'lesson',started:Date.now(),completed:[],events:[],oral:[],exposures:[],question:null,readResult:null,readAttempts:0,played:false,learned:false,listenCheck:0,listenResults:[],reviewQueue:[],reviewIndex:0,reviewAttempts:0,reviewResult:null,reviewDialog:[],deepPhase:'topic',deepTurns:0,deepDialog:[],deepTargetDone:false,deepGuided:false,moduleReports:[],sessionReport:null,aiTurns:0,aiChat:[],savedNotes:[],welcomeTurns:0,ended:false};}
state=beginState();
function sceneSVG(kind='clean'){let dirty=kind==='dirty',tidy=kind==='tidy',hands=kind==='hands';if(hands)return `<svg viewBox="0 0 400 250" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="hbg" x2="0" y2="1"><stop stop-color="#b4e9ff"/><stop offset="1" stop-color="#effbff"/></linearGradient><linearGradient id="skin" x2="1" y2="1"><stop stop-color="#ffd6b4"/><stop offset="1" stop-color="#efad86"/></linearGradient></defs><rect width="400" height="250" fill="url(#hbg)"/><path d="M40 175Q200 130 360 175V250H40Z" fill="#9dd8e7"/><rect x="55" y="174" width="290" height="55" rx="25" fill="#f8fdff"/><ellipse cx="200" cy="195" rx="116" ry="18" fill="#b5e5ef"/><path d="M228 50V25H306V46H257V95" stroke="#84a8b8" stroke-width="17" fill="none" stroke-linejoin="round"/><path d="M252 93L250 149M263 97L267 152M240 95L233 142" stroke="#61c6f6" stroke-width="8" stroke-linecap="round"/><path d="M95 186L176 125Q191 113 201 128L244 170Q248 185 230 193L171 213Z" fill="url(#skin)"/><path d="M289 208L215 147Q199 126 184 141L150 174Q143 189 163 204L214 236Z" fill="url(#skin)"/><g fill="white" opacity=".9"><circle cx="185" cy="145" r="13"/><circle cx="205" cy="155" r="18"/><circle cx="225" cy="166" r="12"/><circle cx="172" cy="170" r="17"/><circle cx="200" cy="183" r="16"/><circle cx="148" cy="135" r="9"/><circle cx="300" cy="120" r="9"/><circle cx="120" cy="81" r="7"/><circle cx="294" cy="72" r="6"/></g><path d="M79 55V81M66 68H92M329 142V166M317 154H341" stroke="#fff" stroke-width="5" stroke-linecap="round"/></svg>`;return `<svg viewBox="0 0 400 250" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="wall" x2="0" y2="1"><stop stop-color="#ffdfaa"/><stop offset="1" stop-color="#fff5d5"/></linearGradient><linearGradient id="floor" x2="0" y2="1"><stop stop-color="#f3bd77"/><stop offset="1" stop-color="#dc9952"/></linearGradient></defs><rect width="400" height="178" fill="url(#wall)"/><path d="M0 178H400V250H0Z" fill="url(#floor)"/><path d="M0 210H400M40 178L10 250M150 178L141 250M260 178L276 250M365 178L398 250" stroke="#cc8d4940" stroke-width="2"/><rect x="31" y="22" width="109" height="107" rx="8" fill="#fff4ce"/><rect x="39" y="30" width="93" height="90" fill="#99dbf1"/><path d="M39 95Q80 45 132 95V120H39" fill="#bbdc86"/><path d="M85 31V120M39 75H133" stroke="#fffae4" stroke-width="6"/><rect x="207" y="116" width="158" height="62" rx="17" fill="#94b88a"/><rect x="218" y="104" width="137" height="34" rx="10" fill="#b9d29c"/><rect x="217" y="167" width="17" height="21" rx="4" fill="#ae7946"/><rect x="339" y="167" width="17" height="21" rx="4" fill="#ae7946"/><rect x="304" y="31" width="54" height="55" rx="5" fill="#c89057"/><rect x="311" y="38" width="40" height="41" fill="#ffe9ae"/><path d="M319 64L330 48L343 65Z" fill="#edb24c"/><circle cx="324" cy="47" r="5" fill="#ffca55"/><ellipse cx="176" cy="214" rx="136" ry="25" fill="#f9de99"/><rect x="46" y="132" width="104" height="60" rx="8" fill="#c48d56"/><rect x="54" y="140" width="88" height="21" fill="#ffe4aa"/><rect x="61" y="146" width="12" height="14" fill="#8ac7c1"/><rect x="79" y="142" width="13" height="18" fill="#f19467"/><rect x="97" y="144" width="13" height="16" fill="#f5c252"/><rect x="116" y="139" width="14" height="21" fill="#87bda0"/><rect x="83" y="112" width="27" height="25" rx="4" fill="#fff3dd"/><path d="M95 116Q70 96 93 95Q87 79 103 85Q126 91 101 115Z" fill="#6fa56b"/><rect x="227" y="181" width="72" height="44" rx="12" fill="#d49e62"/><path d="M227 192H299M240 183V222M256 183V222M272 183V222M288 183V222" stroke="#b8874c" stroke-width="2"/><rect x="235" y="174" width="22" height="16" rx="3" fill="#7cbba6"/><circle cx="276" cy="179" r="12" fill="#efb940"/>${dirty?'<rect x="94" y="189" width="33" height="24" rx="4" fill="#e88564" transform="rotate(-18 110 201)"/><circle cx="162" cy="212" r="14" fill="#76b8d4"/><rect x="191" y="190" width="37" height="23" rx="5" fill="#ffd458" transform="rotate(12 208 200)"/><rect x="59" y="223" width="20" height="16" fill="#8eb57c"/><path d="M318 223L334 231" stroke="#99754a" stroke-width="4"/>':tidy?'<path d="M143 182Q184 165 228 188" stroke="#fff8dd" stroke-width="6" stroke-dasharray="8 6" fill="none"/><path d="M220 177L234 190L217 197" stroke="#fff8dd" stroke-width="6" fill="none"/><rect x="133" y="180" width="23" height="23" rx="5" fill="#ef9168"/>':'<path d="M173 159V183M161 171H185M341 96V116M331 106H351M47 204V220M39 212H55" stroke="#fff9c7" stroke-width="5" stroke-linecap="round"/>'}<circle cx="165" cy="82" r="20" fill="#ffdb9e" opacity=".45"/></svg>`}
function art(kind){const positions={dirty:'0% 0%',clean:'100% 0%',room:'100% 0%',tidy:'0% 100%',hands:'100% 100%'};return `<div class="scene-art" style="background-position:${positions[kind]||positions.clean}" role="img" aria-label="${{dirty:'玩具散落，房间不干净',clean:'整理好的干净房间',room:'房间',tidy:'把玩具收进篮子',hands:'用泡沫和清水洗手'}[kind]||'干净的房间'}"></div>`}
function scene(kind,label=''){return `<div class="scene">${art(kind)}${label?`<span class="scene-label">${escapeHtml(label)}</span>`:''}</div>`}
function progress(n,total){return `<div class="progress-track" aria-label="进度 ${n+1}/${total}">${Array.from({length:total},(_,i)=>`<span class="progress-dot ${i<n?'done':i===n?'current':''}"></span>`).join('')}</div>`}
function button(label,action,disabled=false){return `<button class="primary" onclick="${action}" ${disabled?'disabled':''}>${label} ›</button>`}
function footer(html){return `<div class="footer-action">${html}</div>`}
function head(title,tag=''){return `<header><h1>${title}</h1>${tag?`<span class="tag">${tag}</span>`:''}</header>`}
function bubble(text){panelSpeech=text;return `<div class="speak-line"><button class="round" aria-label="播放雪梨老师的话" onclick="speak(panelSpeech)">◖))</button><span>${escapeHtml(text)}</span></div>`}
function normalize(s){return String(s).toLowerCase().replace(/[’']/g,'').replace(/[^a-z\u4e00-\u9fff]/g,'')}
function storageWrite(){try{localStorage.setItem(STORAGE,JSON.stringify(history.slice(-35)))}catch{toast('浏览器无法保存本地记录，仍可下载报告。')}}
function stopSpeech(){speechSeq++;clearTimeout(speechTimer);if(window.speechSynthesis)speechSynthesis.cancel();stage.classList.remove('speaking');}
function speak(text,lang='zh-CN',done){stopSpeech();const seq=speechSeq;if(!settings.voice||!window.speechSynthesis){if(done)speechTimer=setTimeout(()=>{if(seq===speechSeq)done()},2400/settings.pace);return}stage.classList.add('speaking');const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.9*settings.pace;let completed=false;function finish(){if(completed||seq!==speechSeq)return;completed=true;clearTimeout(speechTimer);stage.classList.remove('speaking');if(done)done()}u.onend=finish;u.onerror=()=>{toast('语音不可用，已显示文字并继续演示。');finish()};speechTimer=setTimeout(finish,Math.max(3200,Math.min(11000,text.length*210))/settings.pace);speechSynthesis.speak(u)}
function navigate(view){clearTimeout(timer);stopSpeech();closeAI();closeModal();state.view=view;render();}
function toast(text){clearTimeout(toastTimer);let e=document.querySelector('#toast');e.textContent=text;e.classList.remove('hidden');toastTimer=setTimeout(()=>e.classList.add('hidden'),3300)}
function resize(){const scale=Math.min(innerWidth/1280,(innerHeight-(document.fullscreenElement?0:58))/590.76923077);stage.style.transform=`scale(${Math.max(.2,scale)})`;}window.addEventListener('resize',resize);document.addEventListener('fullscreenchange',resize);
function isWelcome(){return state.view==='welcome'}
function render(){document.querySelector('#profile-text').innerHTML=escapeHtml(settings.name)+'<small>'+escapeHtml(settings.level)+'<span class="profile-progress"><i style="width:'+Math.max(15,state.completed.length/4*100)+'%"></i></span></small>';stage.className=state.view==='welcome'?'hero':state.view==='goodbye'?'goodbye':'';main.className='panel'+(state.view==='welcome'?' welcome':state.view==='goodbye'?' bye':'')+' view-'+state.view;main.innerHTML=renderView();document.querySelector('#teacher-bubble').textContent=teacherShort();document.querySelector('#welcome-speech').textContent=history.some(r=>r.type==='session')?'又见面啦！今天我们继续一起学英语～':'你好呀，我是雪梨老师～今天我会陪你一起学英语！';document.querySelector('#screen-label').textContent=screenLabel();document.querySelector('#teacher-button').setAttribute('aria-label','点击雪梨老师，播放当前引导');document.querySelector('#mic-label').textContent=['lesson','review','deep','welcome','goodbye'].includes(state.view)?'点击麦克风回答':'随时问雪梨老师';updateMic();resize();}
function teacherShort(){return {library:'今天一起学爱干净！',detail:'课程里我一直陪着你。',path:'每一步，我们一起完成。',lesson:'先完成当前小任务吧！',errors:'先看哪里需要再练。',review:'我记得你刚才的小难点。',deep:'把英语用到生活里吧！',moduleSummary:'每一点进步都看得见！',sessionSummary:'今天的学习完成啦！'}[state.view]||'雪梨老师一直陪着你。'}
function screenLabel(){const names={library:'课程首页 · 衔接页',detail:'课程详情 · 衔接页',welcome:'① 欢迎',path:'学习路径 · 衔接页',lesson:'② 正常课程学习',errors:'③ 错误汇总',review:'④ 针对性二次练习',deep:'⑤ 深度引导',moduleSummary:'⑥ 模块总结',sessionSummary:'⑦ 整次学习总结',goodbye:'⑧ 离场道别',ended:'学习已结束'};return `${names[state.view]||''}${['lesson','errors','review','deep','moduleSummary'].includes(state.view)?' · '+MODULES[state.module].name:''}`}
function renderView(){if(state.view==='library'){panelSpeech='今天我们一起学爱干净，看看怎样让房间和小手变干净。';return head('📚 今天学什么？','知识点掌握 · 一期')+`<p class="lead">${escapeHtml(settings.name)}，今天雪梨老师陪你一起学：爱干净的一天。</p><div class="split-cards"><div class="course-card active">${scene('tidy')}<h2>爱干净的一天</h2><div class="muted">A Clean Day · ${settings.level}</div></div><div class="course-card">${scene('hands')}<h2>生活里的好习惯</h2><span class="badge-locked">课程相关拓展 · 今日课程内体验</span></div><div class="course-card">${scene('clean')}<h2>学习小计划</h2><div class="muted">听绘本 → 学单词<br>读绘本 → 练绘本</div></div></div>`+footer(button('查看今天的课程',"navigate('detail')"));}
if(state.view==='detail'){panelSpeech='今天的故事是爱干净的一天。先听故事，再学单词、读句子，最后做练习。';return head('📖 爱干净的一天',settings.level)+`<div class="cover-row"><div class="course-cover">${scene('tidy')}<h2 style="margin-top:12px">A Clean Day</h2></div><div><h2>从一个干净的房间开始</h2><div class="meta-grid"><span>主题：生活习惯</span><span>4 个学习模块</span><span>约 8–12 分钟</span></div><p class="lead">核心表达：clean · room · dirty · tidy · not<br>This room is not clean.<br>生活拓展：wash hands</p><div class="muted">听懂故事，认识词义，开口读句子，再用练习验证理解。<br>遇到问题可以随时问雪梨老师，课程结束后一起补强。</div><div class="hero-tag">听绘本 → 学单词 → 读绘本 → 练绘本 → AI 复习</div></div></div>`+footer(button('开始今天的学习','startCourse()'));}
if(state.view==='welcome'){const again=history.some(r=>r.type==='session');panelSpeech=again?`${settings.name}，又见面啦！今天我继续陪你学英语。我们一起把房间变干净吧！`:`你好呀，${settings.name}！我是雪梨老师，今天我会陪你一起学英语！我们一起学爱干净吧。`;return head('爱干净的一天 · A Clean Day')+`<div class="welcome-layout"><div class="welcome-illustration">${art('tidy')}</div><div><div class="welcome-message">${escapeHtml(panelSpeech)}</div><div class="hero-tag">${settings.level} · 今日课程「爱干净的一天」</div><div class="countdown">欢迎话术结束后自动进入学习；点击老师可重听。</div></div></div>`+footer(button('我们开始吧',"navigate('path')"));}
if(state.view==='path'){const next=state.completed.length;panelSpeech=next===4?'四个学习模块都完成啦，我们来看看今天的收获。':`现在我们一起${MODULES[next].name}，完成后再进入下一步。`;return head('🌟 今天的学习小旅程',`${state.completed.length} / 4 已完成`)+`<p class="lead">课程始终是主线，老师会在需要时解释、补强，再带你往前走。</p><div class="path">${MODULES.map((m,i)=>`<div class="node ${state.completed.includes(i)?'done':i>next?'locked':''}"><button class="node-icon" onclick="pathClick(${i})" aria-label="${m.name}${i>next?'，未解锁':''}">${state.completed.includes(i)?'✓':i>next?'🔒':m.icon}</button><div class="node-title">${m.name}</div><div class="node-status">${state.completed.includes(i)?'已完成 · 查看模块报告':i>next?'完成前一步后解锁':'现在开始吧'}</div></div>${i<3?'<div class="path-arrow">›</div>':''}`).join('')}</div><div class="notebook" style="margin-top:20px;font-size:16px">每个模块后：查看薄弱点 → 针对性补练 → 生活引导 → 模块总结。<br><span class="muted">已通过的薄弱点会更新掌握状态；需要再练的内容带入下次计划。</span></div>`+footer(button(next===4?'查看今日学习总结':`开始${MODULES[next].name}`,next===4?"finishSession()":`startModule(${next})`));}
if(state.view==='lesson')return renderLesson();if(state.view==='errors')return renderErrors();if(state.view==='review')return renderReview();if(state.view==='deep')return renderDeep();if(state.view==='moduleSummary')return renderModuleSummary();if(state.view==='sessionSummary')return renderSessionSummary();if(state.view==='goodbye')return renderGoodbye();if(state.view==='ended'){panelSpeech='今天已经完成，可以休息了。明天见！';return head('今天的学习已经结束 🌙')+`<div class="completion">✓</div><div style="text-align:center">${bubble('今天已经完成，可以休息了。明天见！')}<p class="lead">这次学习报告已保存在家长中心。<br>浏览器标签页可以直接关闭。</p><button class="subbutton" onclick="openParent()">查看家长报告</button></div>`+footer('<span class="muted">演示人员需要重放时，请使用屏幕外的“重置演示”。</span>');}return '';}
function speakTeacher(){if(state.view==='welcome'){clearTimeout(timer);speak(panelSpeech,'zh-CN',()=>{if(state.view==='welcome')navigate('path')})}else speak(panelSpeech)}
function startCourse(){navigate('welcome');timer=setTimeout(()=>speak(panelSpeech,'zh-CN',()=>{if(state.view==='welcome')navigate('path')}),400)}
function pathClick(i){if(state.completed.includes(i)){openReport(state.moduleReports.find(r=>r.moduleIndex===i));return}if(i>state.completed.length){toast('先完成当前模块，再解锁下一步哦。');return}startModule(i)}
function startModule(i){state.module=i;state.index=0;state.sub='lesson';state.question=null;state.readResult=null;state.readAttempts=0;state.played=false;state.learned=false;state.listenCheck=0;state.listenResults=[];state.aiTurns=0;state.aiChat=[];state.reviewQueue=[];state.deepDialog=[];state.deepTurns=0;state.deepPhase='topic';state.deepTargetDone=false;state.deepGuided=false;navigate('lesson');}
function exposure(key){if(!state.exposures.some(e=>e.module===state.module&&e.key===key))state.exposures.push({module:state.module,key});}
function event(key,pass,source,detail,mode='independent'){const item={key,pass,source,detail,mode,module:state.module,time:Date.now()};state.events.push(item);return item}
function childSpeech(text,source,simulated=true){state.oral.push({module:state.module,text,source,simulated,time:Date.now()})}
function lastEvidence(key,module){const filtered=state.events.filter(e=>e.key===key&&(module===undefined||e.module===module));return filtered.at(-1)}
function mastery(key,module){let e=lastEvidence(key,module);return !e?'unseen':e.pass&&e.mode==='independent'?'mastered':'review'}
function moduleKeys(m=state.module){return [...new Set([...state.exposures.filter(e=>e.module===m).map(e=>e.key),...state.events.filter(e=>e.module===m).map(e=>e.key)])]}
function currentKey(){if(state.view==='review')return state.reviewQueue[state.reviewIndex]?.key||'clean';if(state.view==='deep')return 'wash';if(state.module===0)return state.sub==='check'?(state.listenCheck?'not':'clean'):STORIES[state.index]?.key||'clean';if(state.module===1)return WORDS[state.index]||'clean';if(state.module===2)return READS[state.index]?.keys[0]||'room';return QUIZ[state.index]?.key||'clean'}
function currentTask(){if(state.view==='lesson'){return MODULES[state.module].name+' · '+(state.module===0?(state.sub==='check'?'听后理解题':'听第 '+(state.index+1)+' 页故事'):state.module===1?'第 '+(state.index+1)+' 张词卡':state.module===2?'第 '+(state.index+1)+' 句跟读':'第 '+(state.index+1)+' 道理解题')}return {review:'补练当前知识点',deep:'爱干净主题理解与 wash hands 表达',errors:'查看薄弱知识点',moduleSummary:'查看模块学习结果',sessionSummary:'结束今天学习'}[state.view]||'今天的爱干净课程'}
function renderLesson(){let m=state.module;if(m===0){if(state.sub==='check')return listenCheckpoint();let s=STORIES[state.index];panelSpeech=`我们听这一页：${s.cn}。听完以后，再进入下一页。`;return head('📖 爱干净的一天 · 听绘本',`${state.index+1} / ${STORIES.length}`)+`<div class="two-col"><div>${scene(s.scene,s.cn)}<div class="story-pages">${STORIES.map((_,i)=>`<button class="${i<state.index?'done':i===state.index?'active':''}" ${i>state.index?'disabled':''} onclick="revisitStory(${i})" aria-label="重听第${i+1}页">${i+1}</button>`).join('')}</div></div><div class="learn-detail"><div class="story-title">A Clean Day</div><div class="sentence" id="sentence">${escapeHtml(s.en)}</div><div class="translation">${escapeHtml(s.cn)}</div><button class="round" aria-label="朗读当前绘本句子" onclick="playStory()">◖))</button><button class="subbutton" onclick="playStory(.72)">慢速听一遍</button><div class="lesson-hint">点击喇叭听句子，跟随高亮词语看一看。<br>随时点右下角麦克风提问。</div><div id="play-status" class="question-number">${state.played?'这一页已经听过啦 ✓':'请先听一遍，再继续'}</div></div></div>`+footer(button(state.index===STORIES.length-1?'试试听懂了没有':'下一页','nextStory()',!state.played));}
if(m===1){let k=WORDS[state.index],w=KNOWLEDGE[k];panelSpeech=`今天认识 ${w.en}。${w.en} 是 ${w.cn}。看一看图片，再选出它的意思。`;return head('🔤 学单词',`${state.index+1} / ${WORDS.length}`)+`<div class="two-col"><div>${scene(w.scene)}<div class="lesson-nav" style="margin-top:12px">${progress(state.index,WORDS.length)}<span class="muted">爱干净主题词卡</span></div></div><div class="learn-detail"><div class="word-big">${w.en}</div><button class="round" aria-label="单词标准发音" onclick="speakWord()">◖))</button><button class="subbutton" onclick="showMeaning()">查看释义</button><button class="subbutton" onclick="speakWord(true)">慢速教学</button><div id="meaning" class="translation">${state.learned?w.cn:'点击释义，认识这个词。'}</div><div class="options-title">${w.en} 是什么意思？</div><div class="mini-options">${wordOptions(k).map((v,i)=>`<button class="choice ${state.question?.chosen===i?'chosen':''}" onclick="answerWord(${i})" ${state.question?'disabled':''}>${v}</button>`).join('')}</div>${state.question?`<div class="feedback ${state.question.pass?'':'error'}">${state.question.pass?'选对啦！你认识这个词的意思了。':`${w.en} 是“${w.cn}”。老师记下了这个小难点，稍后一起练。`}</div>`:''}</div></div>`+footer(button(state.index===WORDS.length-1?'完成单词学习':'下一个单词','nextWord()',!state.question));}
if(m===2){let r=READS[state.index];panelSpeech=`看图片，说一说：${r.en} 你可以点击麦克风开口。`;return head('🎙 读绘本 · 开口读一句',`${state.index+1} / ${READS.length}`)+`<div class="two-col"><div>${scene(r.scene)}<div class="lesson-hint">点击麦克风模拟孩子跟读，不上传录音。</div></div><div class="learn-detail"><div class="sentence">${escapeHtml(r.en)}</div><div class="translation">${r.cn}</div><button class="round" aria-label="句子标准发音" onclick="speak('${escapeHtml(r.en)}','en-US')">◖))</button><button class="subbutton" onclick="speak('${escapeHtml(r.en)}','en-US')">再听一遍</button>${state.readResult?`<div class="feedback ${state.readResult.pass?'':'error'}" style="margin-top:16px">${escapeHtml(state.readResult.text)}</div><div class="stars">${state.readResult.pass?'★★★':state.readAttempts>=2?'★☆☆':'★★☆'}</div>`:bubble('先听标准句子，再试着完整说出来。')}<div class="muted-alert">跟读识别与评分使用演示规则，不代表真实发音评测。</div></div></div>`+footer(button(state.index===READS.length-1?'完成绘本跟读':'下一句','nextRead()',!(state.readResult&&(state.readResult.pass||state.readAttempts>=2))));}
let q=QUIZ[state.index];panelSpeech=q.title;return head('✏️ 练绘本 · 试着自己做',`${state.index+1} / ${QUIZ.length}`)+`<p class="lead">${q.title} <button class="subbutton" onclick="speak('${q.en}','en-US')">◖)) 听题</button></p><div class="mini-options" style="justify-content:center;margin-top:16px">${q.options.map((o,i)=>`<button aria-label="${escapeHtml(o.label)}" class="choice ${q.type==='picture'?'picture-choice':''} ${state.question?.chosen===i?'chosen':''}" onclick="answerQuiz(${i})" ${state.question?'disabled':''}>${o.scene?scene(o.scene):''}<div style="margin-top:8px">${escapeHtml(o.label)}</div></button>`).join('')}</div>${state.question?`<div class="feedback ${state.question.pass?'':'error'}">${state.question.pass?'答对啦，你把这个表达用对了！':`${knowledgeFeedback(q.key)} 老师会陪你再练一次。`}</div>`:'<div class="muted" style="text-align:center">先想一想，再选出你的答案。</div>'}`+footer(button(state.index===QUIZ.length-1?'完成本模块':'下一题','nextQuiz()',!state.question));}
function playStory(rate){if(state.played){speak(STORIES[state.index].en,'en-US');return}clearTimeout(timer);let s=STORIES[state.index];const words=s.en.split(' ');let at=0;const index=state.index;const node=document.querySelector('#sentence');function highlight(){if(state.view!=='lesson'||state.index!==index||!node)return;node.innerHTML=words.map((w,i)=>`<span class="${i===at?'lit':''}">${escapeHtml(w)}</span>`).join(' ');at++;if(at<words.length)timer=setTimeout(highlight,480/(rate||settings.pace))}highlight();const previous=settings.pace;if(rate)settings.pace=rate;speak(s.en,'en-US',()=>{settings.pace=previous;if(state.view==='lesson'&&state.module===0&&state.index===index){state.played=true;exposure(s.key);render();}});settings.pace=previous;}
function revisitStory(i){if(i>state.index)return;state.index=i;state.played=false;render();}
function nextStory(){if(!state.played)return;if(state.index<STORIES.length-1){state.index++;state.played=false;render()}else{state.sub='check';state.question=null;render()}}
function listenCheckpoint(){const n=state.listenCheck,key=n?'not':'clean',options=n?['This room is clean.','This room is not clean.']:['干净的','脏的'],correct=n?1:0;panelSpeech=n?'房间不干净，要怎样表达？':'听完故事，clean 是什么意思？';return head('📖 听完了，试着想一想',`理解验证 ${n+1} / 2`)+`<div class="two-col"><div>${scene(n?'dirty':'clean')}</div><div class="learn-detail"><h2>${panelSpeech}</h2><div class="mini-options">${options.map((v,i)=>`<button class="choice" onclick="answerListen(${i})" ${state.question?'disabled':''}>${escapeHtml(v)}</button>`).join('')}</div>${state.question?`<div class="feedback ${state.question.pass?'':'error'}">${state.question.pass?'听懂啦！这次判断正确。':knowledgeFeedback(key)}</div>`:bubble('根据刚才的故事来回答，不确定也没关系。')}</div></div>`+footer(button(n?'看看本轮需要复习什么':'下一小题','nextListenCheck()',!state.question));}
function answerListen(i){if(state.question)return;let key=state.listenCheck?'not':'clean',pass=i===(state.listenCheck?1:0);state.question={pass,chosen:i};event(key,pass,'听后理解题',pass?'词义与否定理解正确':knowledgeFeedback(key));render()}
function nextListenCheck(){if(!state.question)return;if(!state.listenCheck){state.listenCheck=1;state.question=null;render()}else finishModuleLearning()}
function wordOptions(k){return {clean:['干净的','脏的'],room:['洗手','房间'],dirty:['脏的','整理'],tidy:['房间','整理']}[k]}
function wordCorrect(k){return {clean:0,room:1,dirty:0,tidy:1}[k]}
function showMeaning(){state.learned=true;render()}
function speakWord(slow=false){let k=WORDS[state.index];exposure(k);if(slow){const prev=settings.pace;settings.pace=.65;speak(KNOWLEDGE[k].en,'en-US');settings.pace=prev}else speak(KNOWLEDGE[k].en,'en-US')}
function answerWord(i){if(state.question)return;let k=WORDS[state.index],pass=i===wordCorrect(k);state.question={pass,chosen:i};exposure(k);event(k,pass,'单词词义判断',pass?'词义选择正确':'词义选择错误');render()}
function nextWord(){if(!state.question)return;if(state.index<WORDS.length-1){state.index++;state.question=null;state.learned=false;render()}else finishModuleLearning()}
function knowledgeFeedback(key){return {clean:'clean 表示“干净的”，不是“脏的”。',room:'room 是“房间”，需要再认一认。',dirty:'dirty 表示“脏的”，和 clean 的意思不同。',tidy:'tidy 表示“整理”，不是房间的名称。',not:'not 表示“不”。描述不干净时，完整句子里不能漏掉 not。',sentence:'完整表达是 This room is not clean.，要把 not 说出来。',wash:'吃饭前要 wash hands，先把小手洗干净。'}[key]}
function evaluateUtterance(text,keys){const n=normalize(text);if(keys.includes('not')&&!n.includes('not'))return {pass:false,text:'刚才完整句里漏掉了 not。not 表示“不”，再听一次，试着把它说出来。'};let key=keys[0],target=state.view==='review'?KNOWLEDGE[key].en:READS[state.index]?.en||KNOWLEDGE[key].en;let exact=n===normalize(target);return {pass:exact,text:exact?'这次完整表达说出来了，目标词也很清楚！':`刚才的表达还不完整。我们先听：${target}，再试一次。`}}
function acceptRead(text,force){if(state.readResult?.pass||state.readAttempts>=2)return;let r=READS[state.index];state.readAttempts++;childSpeech(text,'绘本跟读');let res=force==='unclear'?{pass:false,text:'room 的声音还可以再清楚一点，先听老师读，再试一次。'}:evaluateUtterance(text,r.keys);state.readResult=res;r.keys.forEach(k=>event(k,res.pass,'绘本跟读',res.text));if(!res.pass&&state.readAttempts>=2){state.readResult.text+=' 已尝试两次，现在跟着老师读一次，稍后再做针对性补练。';r.keys.forEach(k=>event(k,false,'跟读降级',res.text,'guided'));}closeAI();render();speak(state.readResult.text)}
function nextRead(){if(!(state.readResult&&(state.readResult.pass||state.readAttempts>=2)))return;if(state.index<READS.length-1){state.index++;state.readResult=null;state.readAttempts=0;render()}else finishModuleLearning()}
function answerQuiz(i){if(state.question)return;let q=QUIZ[state.index],pass=i===q.correct;state.question={pass,chosen:i};exposure(q.key);event(q.key,pass,'绘本理解习题',pass?'理解题独立答对':knowledgeFeedback(q.key));if(q.key==='not')event('sentence',pass,'绘本理解习题',pass?'完整否定句判断正确':'完整句中的否定词未理解');render()}
function nextQuiz(){if(!state.question)return;if(state.index<QUIZ.length-1){state.index++;state.question=null;render()}else finishModuleLearning()}
function finishModuleLearning(){const failed=moduleKeys().filter(k=>mastery(k,state.module)==='review').sort((a,b)=>KNOWLEDGE[a].priority-KNOWLEDGE[b].priority);state.reviewQueue=failed.slice(0,3).map(key=>({key,original:lastEvidence(key,state.module),initial:true}));state.reviewIndex=0;state.reviewAttempts=0;state.reviewResult=null;state.reviewDialog=[];navigate('errors')}
function errorShort(x){if(x.key==='not'||x.key==='sentence')return '否定表达还没掌握，要把 not 说出来';if(x.original.source.includes('跟读'))return '目标表达不完整或不清楚，需要再读一次';return KNOWLEDGE[x.key].en+' 的意思或用法还需要再分清'}
function renderErrors(){let tested=moduleKeys().filter(k=>lastEvidence(k,state.module)),failed=tested.filter(k=>mastery(k,state.module)==='review');panelSpeech=failed.length?`这轮有 ${failed.length} 个知识点需要再练，我们先补强最重要的 ${state.reviewQueue.length} 个。`:tested.length?'本轮判断都正确，不用把已经会的内容重复做题。我们把它用到生活里吧。':'这一轮认识了新内容，接下来用生活问题验证理解。';return head('📋 模块总结与复习 · 错误汇总',`${MODULES[state.module].name}`)+`<p class="lead">${panelSpeech}</p><div class="content-area">${state.reviewQueue.length?state.reviewQueue.map((x,i)=>`<div class="review-row"><div><strong>${escapeHtml(KNOWLEDGE[x.key].en)}</strong><div><small>${escapeHtml(x.original.source)} · ${escapeHtml(errorShort(x))}</small></div></div><span class="tag">${i+1} / ${state.reviewQueue.length} 重点补强</span></div>`).join(''):`<div class="score-card"><div class="stars">★★★</div><h2>这一轮的理解验证都通过啦！</h2><p class="muted">已验证：${tested.map(k=>escapeHtml(KNOWLEDGE[k].en)).join(' · ')}<br>仅听过或看过的内容不会直接算成“已掌握”。</p></div>`}<div class="footnote">答错或模拟跟读未通过 → 进入复习；一次停顿或耗时偏长仅给提示，不自动判为未掌握。每轮最多补强 3 项。</div></div>`+footer(button(state.reviewQueue.length?'开始复习':'进入生活小挑战',state.reviewQueue.length?'startReview()':'startDeep()'));}
function startReview(){state.reviewAttempts=0;state.reviewResult=null;let item=state.reviewQueue[state.reviewIndex];state.reviewDialog=[{role:'teacher',text:`刚才${item.original.source}中，${item.original.detail} 我们再练 ${KNOWLEDGE[item.key].en}，先听标准表达，再试一次。`}];navigate('review')}
function renderReview(){const item=state.reviewQueue[state.reviewIndex],k=item.key,w=KNOWLEDGE[k];panelSpeech=state.reviewDialog.at(-1)?.text||'我们再试一次吧。';return head('🎯 只练当前这一个小难点',`${state.reviewIndex+1} / ${state.reviewQueue.length} 知识点`)+`<div class="two-col"><div>${scene(w.scene)}<div class="sentence" style="font-size:${w.en.length>12?20:30}px;margin-top:8px;text-align:center">${escapeHtml(w.en)} <button class="subbutton" onclick="speak('${escapeHtml(w.en)}','en-US')">◖)) 标准发音</button></div></div><div><div class="score-card"><h2>${state.reviewResult?.pass?'Well done!':state.reviewResult?.guided?'跟着老师完成啦':'我们一起再试试'}</h2><div class="stars">${state.reviewResult?.pass?'★★★':state.reviewResult?.guided?'★☆☆':'☆☆☆'}</div><div class="muted">${state.reviewResult?.pass?'独立通过，更新为已掌握':state.reviewResult?.guided?'完成跟读，仍保留待巩固':'还没有作答，点击麦克风试一次'}</div></div><div class="prompt" style="margin-top:10px">${escapeHtml(panelSpeech)}</div><div class="mini-options"><button class="subbutton" onclick="speak('${escapeHtml(w.en)}','en-US')">再听一遍</button><button class="subbutton" onclick="reviewHint()">提示一下</button></div>${state.reviewDialog.filter(x=>x.role==='child').length?`<div class="review-child">你刚才说：${escapeHtml(state.reviewDialog.filter(x=>x.role==='child').at(-1).text)}</div>`:''}<div class="muted-alert">独立尝试最多 2 次，之后进入跟读。提示和朗读不计为已掌握。</div></div></div>`+footer(state.reviewResult?.guidedPending?button('跟老师读一遍，再继续','guidedReview()'):button(state.reviewIndex===state.reviewQueue.length-1?'进入生活小挑战':'下一个知识点','nextReview()',!state.reviewResult?.done));}
function reviewHint(){const key=currentKey();panelSpeech=knowledgeFeedback(key)+' 听标准表达，再试着自己说出来。';state.reviewDialog.push({role:'teacher',text:panelSpeech});render();speak(panelSpeech)}
function acceptReview(text,force){if(state.reviewResult?.done||state.reviewResult?.guidedPending)return;let k=currentKey();state.reviewAttempts++;childSpeech(text,'针对性补练');let res=force==='unclear'?{pass:false,text:`${KNOWLEDGE[k].en} 的目标表达还不够清楚，先听标准表达，再试一次。`}:evaluateUtterance(text,[k]);event(k,res.pass,'独立二次练习',res.text);if(k==='sentence')event('not',res.pass,'独立二次练习',res.text);state.reviewDialog.push({role:'child',text},{role:'teacher',text:res.text});if(res.pass)state.reviewResult={pass:true,done:true};else if(state.reviewAttempts>=2){state.reviewResult={guidedPending:true,done:false};state.reviewDialog.push({role:'teacher',text:`已经试了两次，现在一起跟读 ${KNOWLEDGE[k].en}。完成后继续流程，这个小难点下次再练。`})}else state.reviewResult={pass:false,done:false};closeAI();render();speak(panelSpeech)}
function guidedReview(){let k=currentKey();childSpeech(KNOWLEDGE[k].en,'提示后跟读');event(k,false,'跟读降级','跟随标准示范完成，未独立验证通过','guided');state.reviewResult={guided:true,done:true};state.reviewDialog.push({role:'teacher',text:'跟着老师读完啦！这次先到这里，下次再练这个知识点。'});render();speak(panelSpeech)}
function nextReview(){if(!state.reviewResult?.done)return;if(state.reviewIndex<state.reviewQueue.length-1){state.reviewIndex++;startReview()}else startDeep()}
function startDeep(){state.deepPhase='topic';state.deepTurns=0;state.deepTargetDone=false;state.deepGuided=false;state.deepDialog=[{role:'teacher',text:'除了整理房间，你还知道哪些爱干净的事情呀？可以用中文告诉我。'}];navigate('deep')}
function renderDeep(){panelSpeech=state.deepDialog.filter(x=>x.role==='teacher').at(-1)?.text||'除了整理房间，还有哪些爱干净的事情呀？';const revealed=state.deepPhase!=='topic';return head('💬 把今天的英语用到生活里',`主题：爱干净 · ${Math.min(state.deepTurns,3)} / 3 轮`)+`<div class="dialog-flow">${state.deepDialog.slice(-3).map(x=>`<div class="message ${x.role==='child'?'child':''}">${escapeHtml(x.text)}</div>`).join('')}</div>${revealed?`<div class="expression-card">${scene('hands')}<div><strong>wash hands</strong><small>洗手 · 饭前和玩耍后</small></div><button class="round" aria-label="听 wash hands" onclick="speak('wash hands','en-US')">◖))</button></div>`:`<div class="life-choice" style="margin:22px 12px"><button class="choice" onclick="deepAnswer('洗手')">🧼 洗手</button><button class="choice" onclick="deepAnswer('收玩具')">🧺 收玩具</button><button class="choice" onclick="deepAnswer('恐龙')">🦕 我想聊恐龙</button></div><div class="muted" style="text-align:center">也可以通过麦克风面板输入中文或英文自由回答。</div>`}`+footer(state.deepPhase==='guided'?button('跟着老师说 wash hands','completeDeepGuided()'):state.deepPhase==='expression'?button('试着说 wash hands','openMic()'):button('看看本模块的收获','finishModule()',!state.deepTargetDone));}
function deepAnswer(text){text=String(text).trim();if(!text||state.deepTargetDone)return;childSpeech(text,'主题深度引导');state.deepTurns++;state.deepDialog.push({role:'child',text});let norm=normalize(text),msg='';if(state.deepPhase==='expression'){const pass=norm===normalize('wash hands')||norm==='iwashmyhands'||norm==='washmyhands';if(pass){state.deepTargetDone=true;state.deepPhase='done';event('wash',true,'生活表达验证','主题理解相关，wash hands 独立说出');exposure('wash');msg='说出来啦！wash hands。饭前和玩耍后记得洗手，也可以提醒爸爸妈妈。这个生活小挑战完成了。';}else if(state.deepTurns>=3){state.deepPhase='guided';msg='我们先不增加新内容，一起跟读 wash hands。把小手洗干净，就是今天的生活好习惯。'}else msg='你已经知道洗手是好习惯。再试着说出英语表达 wash hands，最多再试一次。';}else{const related=/洗手|wash|hand|整理|收.{0,3}玩具|打扫|刷牙|洗澡|擦|清洁|干净|tidy|clean/i.test(text);const weak=/吃饭|玩耍|妈妈|爸爸|food|eat|play/i.test(text);if(related){state.deepPhase='expression';exposure('wash');msg=/洗手|wash|hand/i.test(text)?'对啦！如果手脏了，我们要 wash hands。爸爸妈妈手脏了，也可以提醒他们 wash hands。现在试着说一次 wash hands。':'这个办法也能保持干净！今天只新增一个英语表达：wash hands，意思是洗手。吃饭前要洗手，试着说 wash hands。';if(state.deepTurns>=3){state.deepPhase='guided';msg+=' 我们跟着老师读一遍，然后结束这次引导。';}}else if(state.deepTurns>=3){state.deepPhase='guided';msg='这个问题先到这里，我们一起看看示例：吃饭前洗手，wash hands。跟读这个表达，完成今天的小挑战。';}else msg=weak?'这个和生活有关。我们回到“爱干净”：吃饭前怎样让小手变干净？':'这个很有趣，不过我们先把刚才的问题完成吧。除了整理房间，还有哪些爱干净的事情？';}state.deepDialog.push({role:'teacher',text:msg});closeAI();render();speak(msg)}
function completeDeepGuided(){if(state.deepPhase!=='guided')return;childSpeech('wash hands','生活表达引导跟读');event('wash',false,'生活表达引导跟读','已跟读示例，未独立验证理解与表达','guided');exposure('wash');state.deepGuided=true;state.deepTargetDone=true;state.deepPhase='done';state.deepDialog.push({role:'teacher',text:'跟着老师说完啦！今天先认识 wash hands，下次再自己说一说。'});render();speak(panelSpeech)}
function stats(module){const keys=module===undefined?[...new Set([...state.exposures.map(e=>e.key),...state.events.map(e=>e.key)])]:moduleKeys(module);const mastered=keys.filter(k=>mastery(k,module)==='mastered'),weak=keys.filter(k=>mastery(k,module)==='review'),unseen=keys.filter(k=>mastery(k,module)==='unseen');const oral=state.oral.filter(o=>module===undefined||o.module===module);const resolved=keys.filter(k=>state.events.some(e=>e.key===k&&!e.pass&&(module===undefined||e.module===module))&&mastery(k,module)==='mastered');return {keys,mastered,weak,unseen,oral:oral.length,resolved,independentOral:oral.filter(o=>o.source!=='提示后跟读'&&o.source!=='生活表达引导跟读').length}}
function finishModule(){if(!state.deepTargetDone)return;const i=state.module;if(!state.completed.includes(i))state.completed.push(i);state.completed.sort();const s=stats(i),r={id:state.id+'-module-'+i,type:'module',moduleIndex:i,title:MODULES[i].name+' · 学习报告',course:COURSE.title,profile:{name:settings.name,level:settings.level},generated:Date.now(),statistics:s,events:state.events.filter(e=>e.module===i),oral:state.oral.filter(e=>e.module===i),nextReview:s.weak,context:{course:COURSE.title,theme:COURSE.theme},simulation:'ASR、LLM、RAG及发音评分为本地规则模拟；开口次数统计演示中的孩子回答，非真实录音测量。'};state.moduleReports.push(r);saveReport(r);navigate('moduleSummary')}
function saveReport(r){history=history.filter(x=>x.id!==r.id);history.push(r);storageWrite();if(settings.autoDownload){downloadReport(r);toast('报告已保存家长中心，已发起下载；多次下载可能需浏览器允许。')}else toast('报告已自动保存到家长中心（本地演示）。')}
function statsBar(s,session=false){return `<div class="statbar">${session?`<div class="stat"><strong>${state.completed.length}/4</strong><span> 完成模块</span><small>听 · 学 · 读 · 练</small></div>`:`<div class="stat"><strong>${s.keys.length}</strong><span> 个知识点</span><small>包含已介绍但未验证内容</small></div>`}<div class="stat"><strong>${s.mastered.length}</strong><span> 已掌握</span><small>由独立作答结果判定</small></div><div class="stat"><strong>${s.oral}</strong><span> 次开口</span><small>模拟孩子回答，不计老师朗读</small></div><div class="stat"><strong>${s.resolved.length}</strong><span> 项已补强</span><small>原薄弱点现已独立通过</small></div></div>`}
function summaryCards(s){return `<div class="module-summary"><div class="good-card"><h2>✓ 你已经学会啦</h2>${s.mastered.length?s.mastered.map(k=>`<span class="pill">${escapeHtml(KNOWLEDGE[k].en)}</span>`).join(''):'<p class="summary-line">完成了学习，正在建立词句认识。</p>'}<div class="summary-line">${s.resolved.length?'补练后掌握：'+s.resolved.map(k=>KNOWLEDGE[k].en).join('、'):'认真完成当前任务，就是今天的第一步。'}</div></div><div class="weak-card"><h2>🌱 下次再练一下</h2>${s.weak.length?s.weak.map(k=>`<span class="pill">${escapeHtml(KNOWLEDGE[k].en)}</span>`).join(''):'<p class="summary-line">没有遗留错误，下次简短回顾。</p>'}${s.unseen.length?`<div class="summary-line muted">仅介绍、待验证：${s.unseen.map(k=>KNOWLEDGE[k].en).join('、')}</div>`:''}</div></div>`}
function renderModuleSummary(){let r=state.moduleReports.find(r=>r.moduleIndex===state.module),s=r.statistics;panelSpeech=`本模块接触了 ${s.keys.length} 个知识点，独立掌握 ${s.mastered.length} 个，模拟开口 ${s.oral} 次。${s.weak.length?'还有 '+s.weak.length+' 个下次再练。':'这轮没有遗留错题。'} 继续加油！`;return head('📋 模块练习情况 AI 总结',MODULES[state.module].name)+statsBar(s)+summaryCards(s)+`<div class="summary-actions"><button class="subbutton" onclick="openReport(state.moduleReports.find(r=>r.moduleIndex===state.module))">查看具体反馈与学习记录</button><span class="report-badge">✓ 已保存到家长中心 · 本地演示</span></div>`+footer(button(state.completed.length===4?'查看整次学习总结':'继续下一模块',state.completed.length===4?'finishSession()':"navigate('path')"));}
function finishSession(){if(state.completed.length!==4){toast('请先完成听、学、读、练四个模块。');return}if(!state.sessionReport){const s=stats();state.sessionReport={id:state.id+'-session',type:'session',title:'今日综合学习报告',course:COURSE.title,profile:{name:settings.name,level:settings.level},generated:Date.now(),completedModules:state.completed.map(i=>MODULES[i].name),statistics:s,moduleReports:state.moduleReports.map(r=>r.id),nextReview:s.weak,events:state.events,oral:state.oral,previousSessions:history.filter(r=>r.type==='session').length,simulation:'统计来自本次演示交互，语音识别、发音评分、大模型和知识库为本地规则模拟。'};saveReport(state.sessionReport)}navigate('sessionSummary')}
function renderSessionSummary(){let r=state.sessionReport,s=r.statistics;const old=history.filter(x=>x.type==='session'&&x.id!==r.id).at(-1);panelSpeech=`今天听、学、读、练四个模块都完成啦！你独立掌握 ${s.mastered.length} 个知识点，${s.weak.length?'下次继续练 '+s.weak.slice(0,2).map(k=>KNOWLEDGE[k].en).join(' 和 ')+'。':'下次先简短回顾今天的表达。'}`;return head('🏆 今天学习完成啦！','整次学习 · 4 个模块')+statsBar(s,true)+`<div class="module-summary"><div class="good-card"><h2>👍 今天做得特别棒</h2><div class="summary-line">✓ 完成听故事、学单词、读句子和理解题</div><div class="summary-line">✓ ${s.mastered.includes('sentence')?'完整否定句里的 not 已经说对了':s.mastered.includes('clean')?'认识并理解了 clean 的意思':'主动参与了课程与复习'}</div><div class="summary-line">✓ ${s.resolved.length?'通过补练，解决了 '+s.resolved.length+' 项薄弱知识':'认真尝试了 '+s.oral+' 次模拟开口'}</div></div><div class="weak-card"><h2>🎯 下次重点练习</h2>${s.weak.length?s.weak.slice(0,3).map(k=>`<div class="summary-line">→ ${escapeHtml(KNOWLEDGE[k].en)}：${KNOWLEDGE[k].cn}</div>`).join(''):'<div class="summary-line">→ 简短回顾 clean、room 和否定句</div><div class="summary-line">→ 用 wash hands 说说生活好习惯</div>'}</div></div><div class="summary-actions"><button class="subbutton" onclick="openParent()">查看家长中心完整报告</button><span class="report-badge">✓ 跨模块合并后，已解决的弱项不再带入明日计划</span></div>`+footer(button('完成今天学习',"navigate('goodbye')"));}
function renderGoodbye(){const s=state.sessionReport.statistics;const plan=s.weak.slice(0,2);panelSpeech=`今天辛苦啦，${settings.name}！${plan.length?'明天我们先复习 '+plan.map(k=>KNOWLEDGE[k].en).join(' 和 ')+'。':'明天先简短回顾今天的表达。'} 新课程准备好后再学习。今天已经完成，可以休息了。明天见！`;return head('今天你真的很棒！💛')+`<div class="lead">今天已经完成，可以休息啦。<br>明天我们继续学习哦～</div><div class="next-plan"><h2>📅 明日的学习计划</h2>${plan.length?plan.map((k,i)=>`<div class="summary-line">${i+1}　复习 ${escapeHtml(KNOWLEDGE[k].en)}（${KNOWLEDGE[k].cn}）</div>`).join(''):'<div class="summary-line">1　回顾今天的词句与 wash hands</div>'}<div class="summary-line">${plan.length+1}　新课程准备好后，再学新内容</div></div><p class="muted">今天不再新增知识。你可以点麦克风和老师说最后一句再见。</p>`+footer(button('明天见 · 退出学习','endSession()'));}
function endSession(){state.ended=true;navigate('ended')}
