function closeAI(){chatOpen=false;ai.classList.add('hidden');updateMic()}
function openMic(){if(state.ended)return;if(state.view==='welcome'){clearTimeout(timer);stopSpeech();timer=setTimeout(()=>{if(state.view==='welcome'){closeAI();speak('我们先开始今天的学习吧。','zh-CN',()=>navigate('path'))}},7000/settings.pace)}chatOpen=true;ai.classList.remove('hidden');updateMic();let options=[],title='雪梨老师一直在课程里陪你',intro='告诉老师你遇到了什么问题吧。';if(state.view==='welcome'){title='和雪梨老师打个招呼';intro='欢迎最多回应一句，随后自动进入今天的课程。';options=[['雪梨老师好！','雪梨老师好！'],['今天学什么？','今天学什么？']];}else if(state.view==='lesson'&&state.module===2){title='试着完整读一句';let target=READS[state.index].en;intro=state.readAttempts>=2||state.readResult?.pass?'这句已完成，请返回课程继续。':'点击一句话模拟识别结果，也可以输入孩子的原话。';if(!state.readResult?.pass&&state.readAttempts<2){options=[[target,target]];if(READS[state.index].keys.includes('not'))options.push(['漏掉 not：This room is clean.','This room is clean.']);else options.push(['目标声音不清晰','unclear']);}}else if(state.view==='review'){title='再练当前的一个知识点';const target=KNOWLEDGE[currentKey()].en;intro=state.reviewResult?.done||state.reviewResult?.guidedPending?'这一轮已完成，请返回页面继续。':'试着说出目标表达。老师会根据本次结果给你反馈。';if(!state.reviewResult?.done&&!state.reviewResult?.guidedPending)options=[[target+' · 独立说对',target],['目标表达还不清楚','unclear']];}else if(state.view==='deep'){title='爱干净的生活小挑战';intro='可以用中文或英文回答，老师会把内容连接到当前主题。';options=state.deepPhase==='topic'?[['洗手','洗手'],['整理玩具','收玩具'],['我想聊恐龙','恐龙']]:state.deepPhase==='expression'?[['wash hands','wash hands'],['表达还没说完整','wash']]:[];}else if(state.view==='goodbye'){title='今天好好结束啦';intro='只回应最后一句道别，不再开始新的学习。';options=[['老师再见！','老师再见！']];}else{const k=currentKey();options=[['这个是什么意思？','这个是什么意思'],[KNOWLEDGE[k].en+' 怎么用？',KNOWLEDGE[k].en+' 怎么用'],['我想聊恐龙','我想聊恐龙']];}
const context=state.view==='deep'?`今日主题：${COURSE.theme} · 当前目标：wash hands`:`今日课程：${COURSE.title} · 当前任务：${currentTask()} · 知识点：${KNOWLEDGE[currentKey()].en}`;
const chat=state.view==='review'?state.reviewDialog:state.view==='deep'?state.deepDialog:state.aiChat;
if(['lesson','review'].includes(state.view))options.push(['我还没想好 · 给我提示','我还没想好']);ai.innerHTML=`<div class="ai-head"><span>🎙 ${title}</span><button class="subbutton" onclick="closeAI()">返回当前任务 ×</button></div><div class="ai-context">${escapeHtml(context)}</div><div class="muted">${intro}</div><div class="chat">${chat.slice(-4).map(x=>`<div class="message ${x.role==='child'?'child':''}">${escapeHtml(x.text)}</div>`).join('')}</div><div class="shortcuts">${options.map((o,i)=>`<button onclick="micShortcut(${i})">${escapeHtml(o[0])}</button>`).join('')}</div><div class="input-row"><input id="ai-input" aria-label="输入孩子的回答" placeholder="输入孩子的问题或回答（语音识别模拟）" onkeydown="if(event.key==='Enter')sendAI()"><button class="subbutton" onclick="sendAI()">发送</button></div><div class="footnote">此 Demo 用文字与预设识别结果演示语音输入；不录音、不请求 API。老师朗读使用浏览器语音。</div>`;ai.dataset.options=JSON.stringify(options);if(!['welcome','goodbye','review','deep'].includes(state.view)&&!(state.view==='lesson'&&state.module===2)&&state.aiTurns>=3){document.querySelector('#ai-input').disabled=true;document.querySelectorAll('#ai-layer .shortcuts button, #ai-layer .input-row button').forEach(b=>b.disabled=true)}setTimeout(()=>document.querySelector('#ai-input')?.focus(),60);}
function micShortcut(i){const opts=JSON.parse(ai.dataset.options||'[]');if(opts[i])dispatchInput(opts[i][1])}
function sendAI(){const el=document.querySelector('#ai-input'),t=el?.value.trim();if(t)dispatchInput(t)}
function dispatchInput(text){if(text==='我还没想好'&&['lesson','review'].includes(state.view)){childSpeech(text,'停顿求助');state.savedNotes.push({category:'pause-hint',module:state.module,knowledge:currentKey(),time:Date.now()});closeAI();toast('慢慢来，先听一遍标准表达。停顿不会直接判错，也不占一次重试。');speak('慢慢来，先听一遍标准表达，再试一次就好。');return}if(state.view==='welcome'){if(state.welcomeTurns)return;state.welcomeTurns++;childSpeech(text,'欢迎回应');clearTimeout(timer);closeAI();speak('你好呀！我们先开始今天的学习吧～','zh-CN',()=>{if(state.view==='welcome')navigate('path')});return}if(state.view==='goodbye'){childSpeech(text,'离场道别');closeAI();speak('明天见！今天已经完成，可以休息了。','zh-CN',endSession);return}if(state.view==='deep'){if(state.deepPhase==='topic'||state.deepPhase==='expression')deepAnswer(text);else toast('这次主题引导已收束，请返回页面继续。');return}if(state.view==='review'){if(text==='unclear')acceptReview(KNOWLEDGE[currentKey()].en,'unclear');else acceptReview(text);return}if(state.view==='lesson'&&state.module===2){if(text==='unclear')acceptRead(READS[state.index].en,'unclear');else acceptRead(text);return}normalAI(text)}
function classifyQuestion(text){if(/杀人|自杀|色情|暴力|银行卡密码|身份证|家庭住址/.test(text))return 'blocked';if(/什么意思|怎么读|怎么用|解释|这个|这句话|这题|答错|clean|room|not|dirty|tidy/i.test(text))return 'course';if(/wash|hand|洗手|刷牙|洗澡|整理|干净|清洁|饭前|爱干净/i.test(text))return 'related';return 'chat'}
function normalAI(text){if(state.aiTurns>=3){closeAI();toast('这个任务的三轮问答已完成，请先继续当前课程。');return}state.aiTurns++;childSpeech(text,'课程主动提问');const category=classifyQuestion(text),k=currentKey();let response='';if(category==='blocked')response='这个内容我们现在不讨论。如果让你觉得不舒服，可以告诉爸爸妈妈。我们回到今天的爱干净课程。';else if(category==='chat')response='这个问题很有趣，不过我们先把当前任务完成吧。今天先学会让房间和小手变干净。';else if(category==='related')response='这和今天的爱干净主题有关。饭前可以 wash hands，意思是洗手。我们先完成当前这一页，生活小挑战里再练一次。';else{let asked=Object.keys(KNOWLEDGE).find(key=>new RegExp('(^|[^a-z])'+KNOWLEDGE[key].en.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z]|$)','i').test(text))||k;response=asked==='not'||asked==='sentence'?'not 表示“不”。This room is not clean. 是“这个房间不干净”。描述不干净时，不能漏掉 not。':`${KNOWLEDGE[asked].en} 是“${KNOWLEDGE[asked].cn}”。${asked==='clean'?'整理好房间，可以说：This room is clean.':asked==='room'?'你学习和休息的房间就是 room。':'把它和今天的房间、清洁图片联系起来，就更容易记住。'} 我们回到当前任务继续。`;}
if(state.aiTurns>=3)response+=' 我们已经聊了三轮，先继续这一页；进入下一项任务后可以再提问。';response=response.slice(0,175);state.aiChat.push({role:'child',text},{role:'teacher',text:response});state.savedNotes.push({module:state.module,category,text,response,context:{course:COURSE.title,task:currentTask(),knowledge:k},time:Date.now()});openMic();speak(response);if(state.aiTurns>=3){document.querySelector('#ai-input').disabled=true;document.querySelectorAll('#ai-layer .shortcuts button, #ai-layer .input-row button').forEach(b=>b.disabled=true);clearTimeout(timer);timer=setTimeout(()=>{if(chatOpen){closeAI();toast('回到当前任务，学习进度已保留。')}},5000/settings.pace)}}
function changeTask(){state.aiTurns=0;state.aiChat=[];closeAI()}
const oldNextWord=nextWord,oldNextQuiz=nextQuiz,oldNextRead=nextRead,oldNextStory=nextStory,oldNextListenCheck=nextListenCheck;
nextWord=function(){changeTask();oldNextWord()};nextQuiz=function(){changeTask();oldNextQuiz()};nextRead=function(){changeTask();oldNextRead()};nextStory=function(){changeTask();oldNextStory()};nextListenCheck=function(){changeTask();oldNextListenCheck()};
function modal(title,body){document.querySelector('#modal').innerHTML=`<div class="modal"><header><h2>${title}</h2><button class="subbutton" onclick="closeModal()">关闭 ×</button></header>${body}</div>`;document.querySelector('#modal').classList.remove('hidden')}
function closeModal(){document.querySelector('#modal').classList.add('hidden')}
function formatDate(t){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(t))}
function openParent(){const courseHistory=history.filter(r=>r.course===COURSE.title);modal('👨‍👩‍👧 家长中心 · 学习报告',`<div class="gesture-note">演示中的模块结果会自动保存到这里，模拟家长端接收。记录仅存在当前浏览器，不上传到远程服务器。报告数字来自本次模拟学习操作。</div><div class="report-list">${courseHistory.length?courseHistory.slice().reverse().map(r=>`<button onclick="openReportById('${r.id}')"><strong>${escapeHtml(r.title)}</strong>　${formatDate(r.generated)}<br><span class="muted">掌握 ${r.statistics.mastered.length} 个 · 待巩固 ${r.statistics.weak.length} 个 · 模拟开口 ${r.statistics.oral} 次</span></button>`).join(''):'<div class="empty">还没有完成模块。学习结束后，报告会自动出现在这里。</div>'}</div>`)}
function openReportById(id){openReport(history.find(r=>r.id===id))}
function reportText(r){const s=r.statistics;let lines=[r.title,'课程：'+r.course,'孩子：'+r.profile.name+' · '+r.profile.level,'已掌握：'+(s.mastered.map(k=>KNOWLEDGE[k].en).join('、')||'暂无独立验证通过内容'),'待巩固：'+(s.weak.map(k=>KNOWLEDGE[k].en).join('、')||'无遗留错误'),'仅介绍待验证：'+(s.unseen.map(k=>KNOWLEDGE[k].en).join('、')||'无'),'模拟开口次数：'+s.oral,'已补强：'+s.resolved.length+' 项'];if(r.completedModules)lines.push('完成模块：'+r.completedModules.join('、'));lines.push('','具体学习记录：');r.events.forEach(e=>lines.push(`${MODULES[e.module].name} · ${KNOWLEDGE[e.key].en} · ${e.mode==='guided'?'提示后完成':e.pass?'独立通过':'需要补强'}：${e.detail}`));lines.push('','下次重点：'+(s.weak.map(k=>KNOWLEDGE[k].en).join('、')||'简短回顾今天的表达'),'',r.simulation);return lines.join('\n')}
function openReport(r){if(!r)return;activeReport=r;modal('📋 '+escapeHtml(r.title),`<pre>${escapeHtml(reportText(r))}</pre><button class="subbutton" onclick="downloadReport(activeReport)">下载这份报告（HTML）</button> <button class="subbutton" onclick="downloadJSON(activeReport)">下载数据（JSON）</button> <button class="subbutton" onclick="openParent()">返回家长中心</button>`)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function downloadReport(r){const html=`<!doctype html><meta charset="utf-8"><title>${escapeHtml(r.title)}</title><style>body{font-family:system-ui;max-width:850px;margin:40px auto;background:#fffdf2;color:#5f3b21;padding:30px}h1{color:#ac762b}pre{white-space:pre-wrap;font:16px/1.9 system-ui;background:white;border:1px solid #eadab6;padding:25px;border-radius:20px}</style><h1>雪梨智学 · ${escapeHtml(r.title)}</h1><p>${formatDate(r.generated)} · 本地功能演示报告</p><pre>${escapeHtml(reportText(r))}</pre>`;downloadBlob(new Blob([html],{type:'text/html;charset=utf-8'}),`雪梨智学-${r.title}-${r.id}.html`)}
function downloadJSON(r){downloadBlob(new Blob([JSON.stringify(r,null,2)],{type:'application/json;charset=utf-8'}),`雪梨智学-${r.title}.json`)}
function topEntry(name){if(name==='家长中心'||name==='学习记录')openParent();else modal(name,`<p>这个入口保留在顶部。本次产品功能 Demo 聚焦「知识点掌握」，商城、积分兑换和活动功能不展开。</p><p class="muted">关闭后继续当前学习，进度会保留。</p>`)}
function openProfile(){modal('👤 今日学习档案',`<p>本演示不接入真实账号，请使用示例称呼。</p><div class="settings-row"><label for="name-input">孩子称呼</label><input id="name-input" maxlength="12" value="${escapeHtml(settings.name)}"></div><div class="settings-row"><label for="level-input">当前 Level</label><select id="level-input"><option ${settings.level==='Level 1'?'selected':''}>Level 1</option><option ${settings.level==='Level 2'?'selected':''}>Level 2</option></select></div><button class="subbutton" onclick="saveProfile()" style="margin-top:15px">保存档案</button>`)}
function saveProfile(){settings.name=(document.querySelector('#name-input').value.trim()||'豆豆').slice(0,12);settings.level=document.querySelector('#level-input').value;closeModal();render()}
function openSettings(){modal('演示设置与说明',`<div class="gesture-note">这是离线的产品功能示意：AI 问答、语义判断、ASR 与评分用本地规则演示；无需密钥。界面风格与 8 个核心阶段参考你的 PDF，学习衔接参考竞品流程。</div><div class="settings-row"><span>老师语音朗读</span><select onchange="settings.voice=this.value==='on';if(!settings.voice)stopSpeech()"><option value="on" ${settings.voice?'selected':''}>开启（浏览器 TTS）</option><option value="off" ${!settings.voice?'selected':''}>关闭 · 保留文字与流程</option></select></div><div class="settings-row"><span>模块 / 整次报告自动下载</span><select onchange="settings.autoDownload=this.value==='on'"><option value="on" ${settings.autoDownload?'selected':''}>开启</option><option value="off" ${!settings.autoDownload?'selected':''}>关闭 · 仍自动存入家长中心</option></select></div><div class="settings-row"><span>朗读与演示节奏</span><select onchange="settings.pace=Number(this.value)"><option value="1" ${settings.pace===1?'selected':''}>正常</option><option value="1.5" ${settings.pace===1.5?'selected':''}>快速讲解</option></select></div><p class="muted">自动下载可能被浏览器的多文件下载策略阻止，家长中心始终提供手动下载。嘴型为简化动画，并非音素级唇形同步。设置只影响当前演示。</p><button class="subbutton" onclick="showGuide()">查看讲解路线与规则</button>`)}
function showGuide(){modal('如何讲解这份 Demo',`<div class="scroll-body"><p><strong>1. 课程主线：</strong>课程入口 → 详情 → 欢迎 → 路径 → 听、学、读、练逐步解锁。每次学习结果触发当前模块的 AI 补强闭环。</p><p><strong>2. 随时提问：</strong>正常课程点麦克风，可输入当前词句疑问、主题相关问题或跑题问题。老师读取当前任务，不另开无限聊天；最多三轮回到当前页。</p><p><strong>3. 观察错误：</strong>故意选错 clean 或漏读 not。错误汇总列出原因，二次练习通过更新为已掌握；连续失败两次降级跟读，仍保留待巩固。</p><p><strong>4. 深度引导：</strong>回答“洗手”或“收玩具”，老师连接到 wash hands。无关回答被拉回主题；最多三轮后引导跟读并结束。</p><p><strong>5. 结果闭环：</strong>模块报告逐次自动保存。四模块完成后，整次报告按最新证据合并掌握状态；已解决的弱项不再进入明日复习。</p><p><strong>6. 明确结束：</strong>离场页只鼓励、提醒下次重点和道别，不新增教学或诱导继续。</p><p class="muted">共 7 个可追踪知识点。听过、看过并不直接算掌握；独立通过才算。停止或耗时异常只提醒，不直接计错。所有识别和评分均为模拟。</p></div>`)}
function confirmReset(){modal('重新开始这次演示？','<p>当前未完成进度会清空。已经保存到家长中心的报告会保留，用于演示再次进入和历史记录。</p><button class="subbutton" onclick="resetDemo()">确认重新开始</button>')}
function resetDemo(){clearTimeout(timer);stopSpeech();closeAI();closeModal();state=beginState();render();toast('已重置本次学习；之前完成的报告仍在家长中心。')}
function fullscreen(){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAI();closeModal();}});
window.addEventListener('beforeunload',stopSpeech);
render();
